'use client';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import axios from 'axios';
import Sidebar from "../components/sidebar";
import Navbar from "../components/Navbar";

export default function Home() {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isAffectationDone, setIsAffectationDone] = useState(false);
  const router = useRouter();

  const handleAffectation = async () => {
    if (isAffectationDone) {
      setError("L'affectation a déjà été réalisée.");
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const response = await axios.post('http://localhost:5000/api/affectation', {}, {
        headers: {
          'Content-Type': 'application/json',
        },
      });

      setResult(response.data);
      setIsAffectationDone(true);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de l'affectation.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-gray-50">
      {/* Sidebar fixe */}
      <div className="fixed left-0 top-0 h-screen w-64 bg-blue-700 text-white shadow-lg transform transition-transform duration-300 ease-in-out">
        <Sidebar />
      </div>

      {/* Contenu principal avec marges pour la Sidebar et la Navbar */}
      <div className="flex flex-col w-full ml-64">
        {/* Navbar fixe */}
        <div className="fixed top-0 left-64 right-0 bg-blue-600 text-white shadow-md z-10">
          <Navbar />
        </div>

        {/* Barre d'affectation (séparée de la Navbar) */}
        <div className="mt-16 p-10 bg-white shadow-lg rounded-lg mx-8 my-6">
          <h1 className="text-3xl text-gray-800 font-bold mb-6">
            Affectation Aléatoire des Tuteurs et Sujets
          </h1>
          <div className="flex space-x-4">
            <button
              onClick={handleAffectation}
              disabled={loading || isAffectationDone}
              className={`px-6 py-3 text-lg ${
                loading || isAffectationDone ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'
              } text-white rounded-lg shadow-md transition-all transform hover:scale-105`}
            >
              {loading ? 'Chargement...' : isAffectationDone ? 'Affectation déjà réalisée' : "Lancer l'affectation"}
            </button>

            <button
              onClick={() => router.push('/affectation')}
              className="px-6 py-3 text-lg bg-green-600 hover:bg-green-700 text-white rounded-lg shadow-md transition-all transform hover:scale-105"
            >
              Aller à la modification
            </button>
          </div>
        </div>

        {/* Contenu défilant (résultats de l'affectation) */}
        <div className="mt-6 p-6 overflow-y-auto mx-8">
          {error && <p className="text-red-500 text-center mb-6">{error}</p>}

          {result && (
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-2xl text-blue-600 font-semibold mb-6">
                Résultats de l'affectation :
              </h2>
              {result.data && result.data.length > 0 ? (
                <div className="space-y-6 w-full">
                  {result.data.map((groupe, index) => (
                    <div
                      key={index}
                      className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 p-6 border border-gray-200 w-full transform hover:scale-101"
                    >
                      {/* Titre du groupe */}
                      <h3 className="text-xl font-semibold text-blue-600 mb-4">
                        Groupe : {groupe.groupeNom}
                      </h3>

                      {/* Tuteur */}
                      <div className="mb-4">
                        <p className="text-sm text-gray-500 font-medium">Tuteur</p>
                        <p className="text-lg text-gray-800">
                          {groupe.tuteurNom ? groupe.tuteurNom : 'Non assigné'}
                        </p>
                      </div>

                      {/* Sujet */}
                      <div className="mb-4">
                        <p className="text-sm text-gray-500 font-medium">Sujet</p>
                        <p className="text-lg text-gray-800">{groupe.sujetTitre}</p>
                      </div>

                      {/* Étudiants */}
                      <div>
                        <p className="text-sm text-gray-500 font-medium">Étudiants</p>
                        <ul className="mt-2 space-y-2">
                          {groupe.etudiants.map((etudiant, i) => (
                            <li key={`${groupe.groupeNom}-${i}`} className="text-gray-700">
                              <span className="text-blue-500 mr-2">•</span>
                              {etudiant}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-gray-600 text-center">Aucun groupe disponible.</p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}